import { test, expect, Page } from '@playwright/test';

test.describe('Login Spinner Display', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/login');
  });

  test('should display spinner while login request is in progress', async () => {
    // Mock the login endpoint to delay response
    await page.route('**/api/login', async (route) => {
      // Delay the response by 2 seconds to simulate async operation
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Fill in login credentials
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');

    await emailInput.fill('test@example.com');
    await passwordInput.fill('password123');

    // Click login button
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify spinner is visible during the request
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Wait for the async request to complete
    await page.waitForLoadState('networkidle');

    // Verify spinner is no longer visible after request completes
    await expect(spinner).not.toBeVisible();
  });

  test('should hide spinner after successful login response', async () => {
    // Mock successful login response with delay
    await page.route('**/api/login', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1500));
      await route.abort('failed');
    });

    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');

    await emailInput.fill('user@test.com');
    await passwordInput.fill('securepass');

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Check spinner appears
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Wait for request to complete
    await page.waitForTimeout(2000);

    // Spinner should be hidden after response
    await expect(spinner).not.toBeVisible();
  });

  test('should display spinner only during async operation and not before', async () => {
    const spinner = page.getByRole('status', { name: /loading/i });

    // Spinner should not be visible initially
    await expect(spinner).not.toBeVisible();

    // Mock login with significant delay
    await page.route('**/api/login', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2500));
      await route.continue();
    });

    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');

    await emailInput.fill('async@test.com');
    await passwordInput.fill('asyncpass');

    // Spinner still should not be visible before clicking
    await expect(spinner).not.toBeVisible();

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Now spinner should appear during async operation
    await expect(spinner).toBeVisible();

    // Wait for completion
    await page.waitForLoadState('networkidle');

    // Spinner should disappear after async completes
    await expect(spinner).not.toBeVisible();
  });

  test('should maintain spinner visibility throughout entire async request duration', async () => {
    const spinner = page.getByRole('status', { name: /loading/i });
    const delayMs = 3000;
    let requestStartTime = 0;
    let spinnerHiddenTime = 0;

    await page.route('**/api/login', async (route) => {
      requestStartTime = Date.now();
      await new Promise(resolve => setTimeout(resolve, delayMs));
      await route.continue();
    });

    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');

    await emailInput.fill('duration@test.com');
    await passwordInput.fill('durationpass');

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify spinner is visible
    await expect(spinner).toBeVisible();

    // Check spinner visibility at intervals during the request
    for (let i = 0; i < 5; i++) {
      await page.waitForTimeout(500);
      const isVisible = await spinner.isVisible();
      if (!isVisible && spinnerHiddenTime === 0) {
        spinnerHiddenTime = Date.now();
      }
    }

    // Wait for request to fully complete
    await page.waitForLoadState('networkidle');

    // Verify spinner is hidden after completion
    await expect(spinner).not.toBeVisible();
  });
});
